CREATE TYPE "VideoProvider" AS ENUM ('LOCAL','MOCK','MUX','CLOUDFLARE_STREAM');
CREATE TYPE "RevisionType" AS ENUM ('FORMULA','REACTION','BIOLOGY_FACT','NCERT_HIGHLIGHT','SHORT_NOTE');
CREATE TABLE "Video" ("id" TEXT PRIMARY KEY,"title" TEXT NOT NULL,"slug" TEXT NOT NULL UNIQUE,"description" TEXT,"examId" TEXT NOT NULL,"subjectId" TEXT NOT NULL,"academicClassId" TEXT NOT NULL,"chapterId" TEXT NOT NULL,"topicId" TEXT NOT NULL,"subtopicId" TEXT,"instructorName" TEXT,"thumbnailUrl" TEXT,"provider" "VideoProvider" NOT NULL DEFAULT 'LOCAL',"providerAssetId" TEXT NOT NULL,"playbackId" TEXT,"durationSeconds" INTEGER,"displayOrder" INTEGER NOT NULL DEFAULT 0,"isFree" BOOLEAN NOT NULL DEFAULT true,"isPublished" BOOLEAN NOT NULL DEFAULT false,"isActive" BOOLEAN NOT NULL DEFAULT true,"publishedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "VideoProgress" ("id" TEXT PRIMARY KEY,"studentId" TEXT NOT NULL,"videoId" TEXT NOT NULL,"watchedSeconds" INTEGER NOT NULL DEFAULT 0,"lastPositionSeconds" INTEGER NOT NULL DEFAULT 0,"completionPercentage" DOUBLE PRECISION NOT NULL DEFAULT 0,"completed" BOOLEAN NOT NULL DEFAULT false,"firstStartedAt" TIMESTAMP(3),"lastWatchedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("studentId","videoId"));
CREATE TABLE "RevisionItem" ("id" TEXT PRIMARY KEY,"title" TEXT NOT NULL,"type" "RevisionType" NOT NULL,"content" TEXT NOT NULL,"examId" TEXT NOT NULL,"subjectId" TEXT NOT NULL,"academicClassId" TEXT NOT NULL,"chapterId" TEXT NOT NULL,"topicId" TEXT NOT NULL,"subtopicId" TEXT,"displayOrder" INTEGER NOT NULL DEFAULT 0,"isPublished" BOOLEAN NOT NULL DEFAULT false,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "Video_chapterId_isPublished_isActive_displayOrder_idx" ON "Video"("chapterId","isPublished","isActive","displayOrder"); CREATE INDEX "Video_topicId_isPublished_isActive_displayOrder_idx" ON "Video"("topicId","isPublished","isActive","displayOrder"); CREATE INDEX "VideoProgress_studentId_lastWatchedAt_idx" ON "VideoProgress"("studentId","lastWatchedAt"); CREATE INDEX "RevisionItem_chapterId_topicId_type_isPublished_isActive_idx" ON "RevisionItem"("chapterId","topicId","type","isPublished","isActive");
ALTER TABLE "Video" ADD FOREIGN KEY ("examId") REFERENCES "Exam"("id"); ALTER TABLE "Video" ADD FOREIGN KEY ("subjectId") REFERENCES "Subject"("id"); ALTER TABLE "Video" ADD FOREIGN KEY ("academicClassId") REFERENCES "AcademicClass"("id"); ALTER TABLE "Video" ADD FOREIGN KEY ("chapterId") REFERENCES "Chapter"("id"); ALTER TABLE "Video" ADD FOREIGN KEY ("topicId") REFERENCES "Topic"("id"); ALTER TABLE "Video" ADD FOREIGN KEY ("subtopicId") REFERENCES "Subtopic"("id"); ALTER TABLE "VideoProgress" ADD FOREIGN KEY ("studentId") REFERENCES "User"("id") ON DELETE CASCADE; ALTER TABLE "VideoProgress" ADD FOREIGN KEY ("videoId") REFERENCES "Video"("id") ON DELETE CASCADE; ALTER TABLE "RevisionItem" ADD FOREIGN KEY ("examId") REFERENCES "Exam"("id"); ALTER TABLE "RevisionItem" ADD FOREIGN KEY ("subjectId") REFERENCES "Subject"("id"); ALTER TABLE "RevisionItem" ADD FOREIGN KEY ("academicClassId") REFERENCES "AcademicClass"("id"); ALTER TABLE "RevisionItem" ADD FOREIGN KEY ("chapterId") REFERENCES "Chapter"("id"); ALTER TABLE "RevisionItem" ADD FOREIGN KEY ("topicId") REFERENCES "Topic"("id"); ALTER TABLE "RevisionItem" ADD FOREIGN KEY ("subtopicId") REFERENCES "Subtopic"("id");
